function renderDashboardCardSettings(){$('dashboardCardSettings').innerHTML=state.settings.dashboardOrder.map((id,i)=>`<div class="list-item dashboard-setting-row"><input type="checkbox" data-card-toggle="${id}" ${state.settings.dashboardHidden.includes(id)?'':'checked'} /><span>${CARD_LABELS[id]}</span><button type="button" data-card-up="${id}" ${i===0?'disabled':''}>↑</button><button type="button" data-card-down="${id}" ${i===state.settings.dashboardOrder.length-1?'disabled':''}>↓</button></div>`).join('')}
function renderAll(){renderSelects();renderDashboard();renderShifts();renderBudget();renderAnalysis();renderSettings()}

function navigate(p){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.dataset.page===p));document.querySelectorAll('.nav-btn').forEach(x=>x.classList.toggle('active',x.dataset.nav===p));location.hash=p;window.scrollTo({top:0,behavior:'smooth'});if(p==='budget')renderBudget();if(p==='analysis')renderAnalysis()}
function openDialog(id){const d=$(id);if(d&&!d.open)d.showModal()}
function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close())}
