function promptAccount(id=''){const a=id?state.accounts.find(x=>x.id===id):null,name=prompt('口座・財布名',a?.name||'');if(!name)return;const type=prompt('種類: bank / cash / emoney',a?.type||'bank')||'bank',balance=num(prompt('現在残高',a?.balance??0)),isSavings=confirm('この口座を「貯金」として扱いますか？');const item={id:a?.id||uid(),name,type:['bank','cash','emoney'].includes(type)?type:'bank',balance,isSavings};const i=state.accounts.findIndex(x=>x.id===item.id);if(i>=0)state.accounts[i]=item;else state.accounts.push(item);persist()}
