function promptCard(id=''){const c=id?state.cards.find(x=>x.id===id):null,name=prompt('カード名',c?.name||'');if(!name)return;const closing=prompt('締め日（1〜31 または end）',c?.closingDay||'end')||'end',pay=prompt('支払日（1〜31 または end）',c?.payDay||'27')||'27',lag=num(prompt('支払い月: 締め月=0 / 翌月=1 / 翌々月=2',c?.payLag??1),1),accName=prompt(`引落口座名\n${state.accounts.map(a=>a.name).join(' / ')}`,account(c?.accountId).name),acc=state.accounts.find(a=>a.name===accName)||state.accounts[0],item={id:c?.id||uid(),name,closingDay:closing,payDay:pay,payLag:lag,accountId:acc.id};const i=state.cards.findIndex(x=>x.id===item.id);if(i>=0)state.cards[i]=item;else state.cards.push(item);persist()}
function promptGoal(id=''){const g=id?state.savingGoals.find(x=>x.id===id):null,name=prompt('目標名',g?.name||'');if(!name)return;const target=num(prompt('目標金額',g?.target??100000)),current=num(prompt('現在貯まっている額',g?.current??0)),monthly=num(prompt('毎月積立予定（0なら収支平均から予測）',g?.monthlyContribution??0)),item={id:g?.id||uid(),name,target,current,monthlyContribution:monthly};const i=state.savingGoals.findIndex(x=>x.id===item.id);if(i>=0)state.savingGoals[i]=item;else state.savingGoals.push(item);persist()}
function promptExpenseTemplate(){const name=prompt('テンプレート名（例：ラーメン）','');if(!name)return;const amount=num(prompt('金額',1000)),category=prompt('カテゴリ','食費')||'その他';state.expenseTemplates.push({id:uid(),name,amount,category,accountId:state.accounts[0]?.id||''});persist()}
function useExpenseTemplate(id){const t=state.expenseTemplates.find(x=>x.id===id);if(!t)return;state.transactions.push({id:uid(),date:todayKey(),type:'expense',name:t.name,amount:num(t.amount),category:t.category,accountId:t.accountId||state.accounts[0]?.id||'',toAccountId:'',cardId:'',note:'テンプレートから追加',receiptData:''});persist();toast(`${t.name} ${yen(t.amount)} を追加しました`)}

function copyShift(id,weeks=1){const s=state.shifts.find(x=>x.id===id);if(!s)return;for(let i=1;i<=weeks;i++)state.shifts.push({...structuredClone(s),id:uid(),date:dateKey(addDays(parseDate(s.date),7*i))});persist();toast(`${weeks}週分コピーしました`)}
function copyPreviousMonth(){const target=shiftViewMonth,prev=addMonths(target,-1),source=shiftsInMonth(prev,$('shiftWorkplaceFilter').value||'all');if(!source.length){toast('前月にシフトがありません');return}if(!confirm(`${source.length}件を今月へコピーしますか？`))return;for(const s of source){const d=parseDate(s.date),day=Math.min(d.getDate(),daysInMonth(target.getFullYear(),target.getMonth()));state.shifts.push({...structuredClone(s),id:uid(),date:dateKey(new Date(target.getFullYear(),target.getMonth(),day,12))})}persist();toast(`${source.length}件コピーしました`)}
function buildSuggestions(){const wp=workplace(state.settings.selectedWorkplaceId),c=nextPayCycle(wp),gp=preset(state.settings.goalPresetId);if(!gp){toast('目標用プリセットを設定してください');return}const st=cycleStats(wp.id,c),remain=Math.max(0,num(state.settings.salaryGoal)-st.forecast),pc=calculatePreset(gp,c.end),need=pc.pay?Math.ceil(remain/pc.pay):0;if(need<=0){toast('目標は達成済みです');return}const start=addDays(new Date(),1),end=parseDate(c.end),cand=[];for(let d=new Date(start);d<=end&&cand.length<need;d=addDays(d,1)){const k=dateKey(d),has=state.shifts.some(s=>s.workplaceId===wp.id&&s.date===k);if(!has)cand.push(k)}suggestedDates=cand;$('suggestionSummary').innerHTML=`不足 ${yen(remain)} / 「${escapeHtml(gp.name)}」ならあと ${need}回。空いている日から ${cand.length}日を候補にしました。`;$('suggestionDates').innerHTML=cand.map(d=>`<button type="button" class="date-select-chip selected" data-suggest-date="${d}">${shortDate(d)}</button>`).join('');$('addSuggestedShiftsBtn').disabled=!cand.length;openDialog('suggestionModal')}
function addSuggested(){const gp=preset(state.settings.goalPresetId);if(!gp)return;for(const d of suggestedDates)state.shifts.push({id:uid(),workplaceId:gp.workplaceId,date:d,planned:{start:gp.start,end:gp.end,breakMinutes:gp.breakMinutes??0},useAutoBreak:!!gp.useAutoBreak,presetId:gp.id,wageOverride:null,transportOverride:gp.transportOverride,distanceKm:0,note:`${gp.name}（目標候補）`});suggestedDates=[];persist();closeDialogs();toast('候補シフトを追加しました')}

function simulatePurchase(){const name=$('purchaseName').value.trim()||'この買い物',price=num($('purchasePrice').value),wp=workplace(state.settings.selectedWorkplaceId),gp=preset(state.settings.goalPresetId),pc=gp?calculatePreset(gp):{pay:0,hours:0},wage=wageForDate(wp.id,todayKey()),hours=wage?price/wage:0,shifts=pc.pay?Math.ceil(price/pc.pay):0,after=spendableAssets()-price,future30=cashflowEvents(todayKey(),dateKey(addDays(new Date(),30))).reduce((s,e)=>s+e.amount,0),safe=after+future30>=num(state.settings.balanceFloor);$('purchaseResult').innerHTML=`<b>${escapeHtml(name)} ${yen(price)}</b><br>労働時間換算：約 ${hoursText(hours)}${gp?` / 「${escapeHtml(gp.name)}」約 ${shifts}回`:''}<br>購入直後の自由資金：${yen(after)}<br>30日以内の予定反映後：${yen(after+future30)}<br><strong class="${safe?'positive':'negative'}">${safe?'現在の設定上は最低残高を維持できます':'最低残高ラインを割る見込みです'}</strong>`}
function renderSearch(q=''){const query=q.trim().toLowerCase();if(!query){$('searchResults').innerHTML='<div class="empty">キーワードを入力してください</div>';return}const rows=[];for(const s of state.shifts){const text=`${s.date} ${workplace(s.workplaceId).name} ${s.note}`.toLowerCase();if(text.includes(query))rows.push({title:`シフト ${s.date} ${workplace(s.workplaceId).name}`,sub:`${s.planned.start}–${s.planned.end} / ${yen(calculateShift(s).pay)}`})}for(const t of state.transactions){const text=`${t.date} ${t.name} ${t.category} ${t.note}`.toLowerCase();if(text.includes(query))rows.push({title:`${t.type==='income'?'収入':'支出'} ${t.name}`,sub:`${t.date} / ${yen(t.amount)} / ${t.category}`})}for(const f of state.fixedCosts)if(`${f.name} ${f.category}`.toLowerCase().includes(query))rows.push({title:`固定費 ${f.name}`,sub:`${yen(fixedAmountOn(f,todayKey()))} / ${f.category}`});for(const p of state.payslips)if(`${workplace(p.workplaceId).name} ${p.payDate}`.toLowerCase().includes(query))rows.push({title:`給与明細 ${workplace(p.workplaceId).name}`,sub:`${p.payDate} / 手取り ${yen(p.net)}`});$('searchResults').innerHTML=rows.slice(0,50).map(r=>`<div class="list-item"><div class="list-main"><div class="list-title">${escapeHtml(r.title)}</div><div class="list-sub">${escapeHtml(r.sub)}</div></div></div>`).join('')||'<div class="empty">見つかりませんでした</div>'}
function resizeReceipt(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const max=700,scale=Math.min(1,max/img.width),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.72))};img.onerror=reject;img.src=r.result};r.onerror=reject;r.readAsDataURL(file)})}
function exportJSON(){downloadBlob(`shiftwallet-${todayKey()}.json`,JSON.stringify(state,null,2),'application/json')}
function exportCSV(){const esc=v=>`"${String(v??'').replaceAll('"','""')}"`;let lines=['type,date,workplace,name,start,end,break_minutes,hours,amount,category,note'];for(const s of state.shifts){const c=calculateShift(s);lines.push(['shift',s.date,workplace(s.workplaceId).name,s.note,s.planned.start,s.planned.end,c.breakMinutes,c.hours,c.pay,'',s.note].map(esc).join(','))}for(const t of state.transactions)lines.push(['transaction',t.date,'',t.name,'','','','',t.type==='income'?t.amount:-t.amount,t.category,t.note].map(esc).join(','));downloadBlob(`shiftwallet-${todayKey()}.csv`,`\ufeff${lines.join('\n')}`,'text/csv;charset=utf-8')}

